.dbconfig defensive off
BEGIN;
PRAGMA writable_schema = on;
PRAGMA foreign_keys = off;
PRAGMA encoding = 'UTF-8';
PRAGMA page_size = '4096';
PRAGMA auto_vacuum = '0';
PRAGMA user_version = '0';
PRAGMA application_id = '0';
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE plugins (
	id INTEGER NOT NULL, 
	uri VARCHAR(255) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	category VARCHAR(100), 
	author VARCHAR(255), 
	version VARCHAR(20), 
	parameters TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, 
	reported_latency_samples INTEGER, 
	measured_latency_samples INTEGER, 
	has_latency_port BOOLEAN, 
	latency_port_index INTEGER, 
	priority INTEGER, 
	auto_bypass_on_overload BOOLEAN, 
	estimated_cpu_us FLOAT, 
	is_hard_rt_capable BOOLEAN, 
	has_options_interface BOOLEAN, 
	has_state_interface BOOLEAN, 
	has_worker_interface BOOLEAN, 
	bundle_path VARCHAR(512), 
	PRIMARY KEY (id), 
	UNIQUE (uri)
);
CREATE TABLE chains (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	is_active BOOLEAN, 
	config TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE midi_mappings (
	id INTEGER NOT NULL, 
	channel INTEGER NOT NULL, 
	cc INTEGER NOT NULL, 
	target_plugin_uri VARCHAR(255), 
	target_param_index INTEGER, 
	min_val FLOAT, 
	max_val FLOAT, 
	is_learned BOOLEAN, 
	created_at DATETIME, chain_id INTEGER, target_param_symbol VARCHAR(100), curve_type VARCHAR(20) DEFAULT 'linear', invert BOOLEAN DEFAULT 0, feedback_enabled BOOLEAN DEFAULT 1, feedback_cc INTEGER, name VARCHAR(255), group_id INTEGER, is_enabled BOOLEAN DEFAULT 1, updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE system_config (
	id INTEGER NOT NULL, 
	"key" VARCHAR(255) NOT NULL, 
	value TEXT NOT NULL, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE ("key")
);
CREATE TABLE ir_categories (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	parent_id INTEGER, 
	description TEXT, 
	icon VARCHAR(50), 
	display_order INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	FOREIGN KEY(parent_id) REFERENCES ir_categories (id)
);
CREATE TABLE command_history (
	id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, 
	session_id VARCHAR(36) NOT NULL, 
	sequence INTEGER NOT NULL, 
	command_type VARCHAR(100) NOT NULL, 
	description VARCHAR(500) NOT NULL, 
	state_before TEXT NOT NULL, 
	state_after TEXT NOT NULL, 
	affected_chain_ids JSON, 
	affected_plugin_uris JSON, 
	is_undone BOOLEAN, 
	executed_at DATETIME NOT NULL, 
	undone_at DATETIME
);
CREATE TABLE session_backups (
	id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, 
	session_name VARCHAR(255) NOT NULL, 
	version INTEGER NOT NULL, 
	chains_snapshot TEXT NOT NULL, 
	presets_snapshot TEXT NOT NULL, 
	midi_mappings_snapshot TEXT NOT NULL, 
	automation_snapshot TEXT, 
	backup_type VARCHAR(50), 
	trigger_reason VARCHAR(255), 
	file_size_bytes INTEGER, 
	created_at DATETIME NOT NULL
);
CREATE TABLE automation_lanes (
	id INTEGER NOT NULL, 
	parameter_id VARCHAR(255) NOT NULL, 
	plugin_uri VARCHAR(255) NOT NULL, 
	param_index INTEGER NOT NULL, 
	param_name VARCHAR(255), 
	points TEXT, 
	enabled BOOLEAN, 
	modulation_source VARCHAR(50), 
	lfo_rate_hz FLOAT, 
	lfo_depth FLOAT, 
	lfo_waveform VARCHAR(20), 
	lfo_phase FLOAT, 
	lfo_sync_to_tempo BOOLEAN, 
	lfo_tempo_division VARCHAR(20), 
	env_input_source VARCHAR(50), 
	env_attack_ms FLOAT, 
	env_release_ms FLOAT, 
	env_threshold_db FLOAT, 
	env_sensitivity FLOAT, 
	loop_enabled BOOLEAN, 
	loop_start FLOAT, 
	loop_end FLOAT, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (parameter_id)
);
CREATE TABLE midi_learn_state (
	id INTEGER NOT NULL, 
	target_plugin_uri VARCHAR(255) NOT NULL, 
	target_param_index INTEGER NOT NULL, 
	target_param_name VARCHAR(255), 
	started_at DATETIME, 
	timeout_seconds FLOAT, 
	completed BOOLEAN, 
	learned_channel INTEGER, 
	learned_cc INTEGER, 
	completed_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE presets (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	chain_id INTEGER, 
	plugin_states TEXT NOT NULL, 
	tags JSON, 
	category VARCHAR(100), 
	description TEXT, 
	is_favorite BOOLEAN, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(chain_id) REFERENCES chains (id)
);
CREATE TABLE chain_plugins (
	id INTEGER NOT NULL, 
	chain_id INTEGER NOT NULL, 
	plugin_uri VARCHAR(255) NOT NULL, 
	position INTEGER NOT NULL, 
	bypass BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(chain_id) REFERENCES chains (id)
);
CREATE TABLE plugin_performance_log (
	id INTEGER NOT NULL, 
	plugin_uri VARCHAR(255) NOT NULL, 
	plugin_name VARCHAR(255) NOT NULL, 
	chain_id INTEGER, 
	avg_time_us FLOAT NOT NULL, 
	max_time_us FLOAT NOT NULL, 
	cpu_percent FLOAT NOT NULL, 
	call_count INTEGER, 
	sample_rate INTEGER NOT NULL, 
	buffer_size INTEGER NOT NULL, 
	deadline_us FLOAT NOT NULL, 
	timestamp DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(chain_id) REFERENCES chains (id)
);
CREATE TABLE plugin_presets (
	id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, 
	name VARCHAR(255) NOT NULL, 
	plugin_uri VARCHAR(255) NOT NULL, 
	plugin_name VARCHAR(255) NOT NULL, 
	parameters TEXT NOT NULL, 
	tags JSON, 
	category VARCHAR(100), 
	description TEXT, 
	is_favorite BOOLEAN, 
	is_default BOOLEAN, 
	usage_count INTEGER, 
	created_at DATETIME, 
	updated_at DATETIME
);
CREATE TABLE impulse_responses (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	file_path VARCHAR(512) NOT NULL, 
	file_hash VARCHAR(64) NOT NULL, 
	sample_rate INTEGER, 
	channels INTEGER, 
	duration_seconds FLOAT, 
	length_samples INTEGER, 
	peak_amplitude FLOAT, 
	rms_level FLOAT, 
	rt60 FLOAT, 
	early_decay_time FLOAT, 
	peak_location_ms FLOAT, 
	estimated_characteristics BOOLEAN, 
	category VARCHAR(100), 
	category_id INTEGER, 
	subcategory VARCHAR(100), 
	library VARCHAR(100), 
	license VARCHAR(100), 
	source_url VARCHAR(512), 
	author VARCHAR(255), 
	description TEXT, 
	tags JSON, 
	created_at DATETIME, 
	updated_at DATETIME, is_favorite INTEGER DEFAULT 0, rating INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (file_path), 
	UNIQUE (file_hash), 
	FOREIGN KEY(category_id) REFERENCES ir_categories (id)
);
CREATE TABLE nam_models (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	file_path VARCHAR(512) NOT NULL, 
	file_hash VARCHAR(64) NOT NULL, 
	file_size INTEGER, 
	model_type VARCHAR(100), 
	sample_rate INTEGER, 
	input_gain FLOAT, 
	output_gain FLOAT, 
	category VARCHAR(100), 
	amp_type VARCHAR(100), 
	amp_name VARCHAR(255), 
	author VARCHAR(255), 
	description TEXT, 
	tags JSON, 
	license VARCHAR(100), 
	created_at DATETIME, 
	updated_at DATETIME, is_favorite INTEGER DEFAULT 0, rating INTEGER, source_url VARCHAR(512), is_featured BOOLEAN DEFAULT 0, featured_position INTEGER DEFAULT NULL, source_tone3000_id VARCHAR(255) DEFAULT NULL, source_tone3000_name VARCHAR(255) DEFAULT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (file_path), 
	UNIQUE (file_hash)
);
CREATE TABLE sqlite_stat1(tbl,idx,stat);
CREATE TABLE midi_mapping_groups (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	description TEXT, 
	color VARCHAR(7), 
	display_order INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE midi_commands (
	id INTEGER NOT NULL, 
	command_type VARCHAR(20) NOT NULL, 
	channel INTEGER, 
	data1 INTEGER NOT NULL, 
	data2 INTEGER, 
	action_type VARCHAR(30) NOT NULL, 
	target_chain_id INTEGER, 
	target_plugin_uri VARCHAR(255), 
	action_data JSON, 
	name VARCHAR(255), 
	is_enabled BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(target_chain_id) REFERENCES chains (id) ON DELETE CASCADE
);
CREATE TABLE midi_routing_rules (
	id INTEGER NOT NULL, 
	channel INTEGER, 
	cc INTEGER NOT NULL, 
	chain_id INTEGER, 
	routing_type VARCHAR(30), 
	routing_data JSON, 
	name VARCHAR(255), 
	is_enabled BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(chain_id) REFERENCES chains (id) ON DELETE CASCADE
);
CREATE TABLE midi_device_configs (
	id INTEGER NOT NULL, 
	device_name VARCHAR(255) NOT NULL, 
	device_type VARCHAR(20), 
	is_enabled BOOLEAN, 
	auto_connect BOOLEAN, 
	channel_filter INTEGER, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (device_name)
);
CREATE TABLE midi_presets (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	description TEXT, 
	mappings_snapshot JSON, 
	commands_snapshot JSON, 
	routing_rules_snapshot JSON, 
	device_configs_snapshot JSON, 
	is_default BOOLEAN, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE chain_midi_configs (
	id INTEGER NOT NULL, 
	chain_id INTEGER, 
	program_number INTEGER NOT NULL, 
	bank_msb INTEGER, 
	bank_lsb INTEGER, 
	send_pc_on_activate BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (chain_id), 
	FOREIGN KEY(chain_id) REFERENCES chains (id) ON DELETE CASCADE
);
CREATE TABLE community_presets (
	id INTEGER NOT NULL, 
	uuid VARCHAR(36) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	plugin_uri VARCHAR(255) NOT NULL, 
	plugin_name VARCHAR(255) NOT NULL, 
	plugin_format VARCHAR(50), 
	parameters TEXT NOT NULL, 
	state_chunk TEXT, 
	author_name VARCHAR(255), 
	author_id VARCHAR(100), 
	description TEXT, 
	category VARCHAR(100), 
	tags JSON, 
	license VARCHAR(50), 
	download_count INTEGER, 
	rating_sum FLOAT, 
	rating_count INTEGER, 
	report_count INTEGER, 
	original_format VARCHAR(50), 
	source_file_hash VARCHAR(64), 
	is_approved BOOLEAN, 
	is_flagged BOOLEAN, 
	is_hidden BOOLEAN, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE flow_snapshots (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	description TEXT, 
	tags JSON, 
	program_number INTEGER, 
	bank_msb INTEGER, 
	bank_lsb INTEGER, 
	snapshot_data TEXT NOT NULL, 
	is_active BOOLEAN, 
	display_order INTEGER, 
	is_favorite BOOLEAN, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (program_number)
);
CREATE TABLE preset_ratings (
	id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, 
	preset_id INTEGER NOT NULL, 
	user_fingerprint VARCHAR(64) NOT NULL, 
	rating INTEGER NOT NULL, 
	review_text TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, 
	FOREIGN KEY(preset_id) REFERENCES community_presets (id) ON DELETE CASCADE
);
CREATE TABLE preset_import_history (
	id INTEGER NOT NULL, 
	source_file_hash VARCHAR(64) NOT NULL, 
	original_filename VARCHAR(255) NOT NULL, 
	original_format VARCHAR(50) NOT NULL, 
	file_size_bytes INTEGER, 
	converted_preset_id INTEGER, 
	community_preset_id INTEGER, 
	conversion_success BOOLEAN, 
	conversion_errors TEXT, 
	target_plugin_uri VARCHAR(255), 
	parameters_imported INTEGER, 
	import_timestamp DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (source_file_hash), 
	FOREIGN KEY(converted_preset_id) REFERENCES plugin_presets (id) ON DELETE SET NULL, 
	FOREIGN KEY(community_preset_id) REFERENCES community_presets (id) ON DELETE SET NULL
);
CREATE TABLE lcd_events (
	event_id VARCHAR(36) NOT NULL, 
	timestamp DATETIME NOT NULL, 
	created_at DATETIME, 
	source_node VARCHAR(50) NOT NULL, 
	event_type VARCHAR(20) NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	message VARCHAR(500) NOT NULL, 
	icon VARCHAR(10) NOT NULL, 
	color VARCHAR(20) NOT NULL, 
	sound INTEGER NOT NULL, 
	dismiss_auto INTEGER NOT NULL, 
	broadcast INTEGER NOT NULL, 
	target_nodes VARCHAR(500) NOT NULL, 
	ttl INTEGER NOT NULL, 
	context JSON NOT NULL, 
	PRIMARY KEY (event_id)
);
CREATE TABLE flow_assignments (
	id INTEGER NOT NULL, 
	flow_id VARCHAR(64) NOT NULL, 
	chain_id INTEGER NOT NULL, 
	assigned_node_id VARCHAR(128) NOT NULL, 
	assignment_type VARCHAR(20), 
	assignment_strategy VARCHAR(20), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (flow_id)
);
CREATE TABLE flow_deployments (
	id INTEGER NOT NULL, 
	flow_id VARCHAR(64) NOT NULL, 
	primary_node_id VARCHAR(128) NOT NULL, 
	standby_node_ids JSON, 
	deployment_status VARCHAR(20), 
	deployment_timestamp DATETIME, 
	last_failover_time DATETIME, 
	error_message TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE node_capabilities (
	id INTEGER NOT NULL, 
	node_id VARCHAR(128) NOT NULL, 
	cpu_cores INTEGER, 
	memory_gb INTEGER, 
	has_gpu BOOLEAN, 
	gpu_name VARCHAR(255), 
	last_updated DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (node_id)
);
CREATE TABLE flow_deployment_history (
	id INTEGER NOT NULL, 
	flow_id VARCHAR(64) NOT NULL, 
	from_node_id VARCHAR(128), 
	to_node_id VARCHAR(128) NOT NULL, 
	action VARCHAR(20) NOT NULL, 
	timestamp DATETIME, 
	notes TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE special_settings (
	id INTEGER NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	hidden_plugins JSON, 
	menu_location VARCHAR(20), 
	version INTEGER, 
	last_updated DATETIME, 
	updated_by_node VARCHAR(128), 
	raft_log_index INTEGER, 
	PRIMARY KEY (id)
);
CREATE TABLE srp_admission_logs (
	id INTEGER NOT NULL, 
	admission_id VARCHAR(64) NOT NULL, 
	decision VARCHAR(16) NOT NULL, 
	reason_code VARCHAR(64) NOT NULL, 
	reason TEXT NOT NULL, 
	remediation JSON, 
	daemon_type VARCHAR(16), 
	daemon_socket VARCHAR(255), 
	raw_response TEXT, 
	endpoint VARCHAR(128) NOT NULL, 
	stream_id VARCHAR(255), 
	talker_id VARCHAR(128), 
	listener_id VARCHAR(128), 
	reservation_id VARCHAR(128), 
	request_metadata JSON, 
	created_at DATETIME NOT NULL, 
	completed_at DATETIME NOT NULL, 
	released BOOLEAN NOT NULL, 
	release_status VARCHAR(16), 
	release_reason TEXT, 
	release_response TEXT, 
	release_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (admission_id)
);
CREATE UNIQUE INDEX ix_community_presets_uuid ON community_presets (uuid);
CREATE UNIQUE INDEX idx_special_settings_singleton ON special_settings (id);
