INSERT OR IGNORE INTO 'nam_models'('id', 'name', 'file_path', 'file_hash', 'file_size', 'model_type', 'sample_rate', 'input_gain', 'output_gain', 'category', 'amp_type', 'amp_name', 'author', 'description', 'tags', 'license', 'created_at', 'updated_at', 'is_favorite', 'rating', 'source_url', 'is_featured', 'featured_position', 'source_tone3000_id', 'source_tone3000_name') VALUES (262, 'Fender_Twin_Reverb_Standard_[TONE3000-289460]', '/home/mm/.local/share/map2/nam/featured/Fender_Twin_Reverb_Standard_[TONE3000-289460].nam', '4b98ad5002efcc71d672c7a0d93912e8f85b09f46861cfb53f11db4dc6f37af6', 282894, 'unknown', 48000, 0, 0, 'Featured Amp', 'standard', 'Fender Twin Reverb', 'desmondstudio', replace('This Amp Capture Set will available soon in our shop :\nhttps://gindabestari.com/desmond-studio\n\nFender Deluxe Reverb ''65 Reissue. Clean Sound. Mic''d with Shure SM57 + Royer Ribbon R-121 + Universal Audio OX for Mono Room Sound (Neumann U67 Modeling in OX)\n\n3 Models Available to Download. Closed Mics with Room, Closed Mics without Room and Room Sound only, so you can blend it in post.\n\nModels :\n- Fender DRRI | Clean | SM57 + Royer R-121 + Room | Full Rig\n- Fender DRRI | Clean | SM57 + Royer R-121 (No Room) | Full Rig\n- Fender DRRI | Clean | Room Only | Full Rig\n- Fender DRRI | Clean | DI Capture No Cab\n\nNEW VERSION Update :\n- The Noise Floor is Lower Than The Previous Version\n- Higher Epochs Than The Previous Version\n- Better Transient Response\n- I Turned Down the Room Level on Microphones Blend (57+121+Room)\n- I Added DI Capture (No Cab)\n\nAmp Setting :\n- Vibrato Channel\n- Volume 3, Bass 5, Treble 7\n\nSpeaker :\n- 12" Jensen® C-12K Speaker\n\nMicrophones :\n- Shure SM57\n- Royer R-121\n- Universal Audio OX (Neumann U67 Microphone Modeling for Mono Room Sound)\n\nAudio Interface, Studio Outboard & Cables:\n- Great River ME-1NV Mic Pre (for SM57)\n- Cranborne Audio EC1 Mic Pre (for Royer R-121)\n- Pair of Warm Audio WA76 FET Compressor REV D (for both SM57 & Royer R-121) as line amplifier (no compression) to increase harmonic content.\n- Little Labs Redeye 3D Phantom Direct Box & Re-Amp Box\n- Universal Audio Apollo Twin Audio Interface\n- Evidence Audio Lyric HG Instrument Cables\n- Mogami 2549 Microphone Cables\n\nEnjoy :)\n\n- Ginda Bestari || Desmond Studio -','\n', char(10)), '["featured", "tone3000", "nam", "fender twin reverb"]', 'TONE3000 Community', '2026-02-04 03:12:57.732505', '2026-02-04 03:13:13.259548', 0, NULL, 'https://www.tone3000.com/api/v1/models/289460/download/lwu0hbx8d6n.nam', 1, 20, '289460', 'NEW VERSION | Fender DRRI | Clean | SM57 + Royer R-121 + Room | Full Rig');
